import React from 'react';
import styled from 'styled-components';

import Color from '../../my_modules/Color';

const Wrapper = styled.div`
  height: 100%;
  box-sizing: border-box;
  justify-content: center;
`;

const Input = styled.input`
  display: none;
`;

const FakeButton = styled.label`
  display: inline-block;
  box-sizing: border-box;
  cursor: pointer;
  text-align: center;
  border: none;
  height: 100%;
  min-width: 4.5em;
  line-height: 1.9em;
  font-size: 1.0em;
  border-radius: 0.2em;
  color: ${Color.White};
  background-color: ${Color.DimGray}; 
  
  &:focus {
    outline: 0;
  }
  &:hover {
    color: ${Color.White};
    background-color: ${Color.DarkGray};
  }
  &:active {
    transform: translateY(2px);
    box-shadow: 0 0 1px rgba(68, 68, 68, 10%);
  }
`;

const FakeButtonMat = styled.label`
  display: inline-block;
  box-sizing: border-box;
  cursor: pointer;
  text-align: center;
  border: none;
  height: 100%;
  min-width: 9.0em;
  line-height: 1.9em;
  font-size: 1.0em;
  border-radius: 0.2em;
  padding:0 0.2em;
  color: ${Color.White};
  background-color: ${Color.DimGray}; 
  
  &:focus {
    outline: 0;
  }
  &:hover {
    color: ${Color.White};
    background-color: ${Color.DarkGray};
  }
  &:active {
    transform: translateY(2px);
    box-shadow: 0 0 1px rgba(68, 68, 68, 10%);
  }
`;


const onChange = (event, cb) => {
  cb(event);
};

export const InputFileButton = (props) => {
  if (props.type !== 'file') return 'type miss';
  return (
    <Wrapper>
      <FakeButton>
        {props.text}
        <Input
          {...props}
          onChange={e => onChange(e, props.onChange)}
        />
      </FakeButton>
    </Wrapper>
  );
};

export const InputFileButtonMat = (props) => {
  if (props.type !== 'file') return 'type miss';
  return (
    <Wrapper>
      <FakeButtonMat>
        {props.text}
        <Input
          {...props}
          onChange={e => onChange(e, props.onChange)}
        />
      </FakeButtonMat>
    </Wrapper>
  );
};

export default InputFileButton;