import styled from 'styled-components';
import Color from '../../my_modules/Color';

const BaseButton = styled.button`
  display: inline-block;
  box-sizing: border-box;
  cursor: pointer;
  text-align: center;
  border: none;
  &:focus {
    outline: 0;
  }
`

export const Button = styled(BaseButton)`
  height: 100%;
  min-width: 4.5em;
  line-height: 1.85em;
  font-size: 1.0em;
  border-radius: 0.2em;
  color: ${Color.White};
  background-color: ${Color.DimGray}; 
  &:hover {
    color: ${Color.White};
    background-color: ${Color.DarkGray};
  }
  &:active {
    transform: translateY(2px);
    box-shadow: 0 0 1px rgba(68, 68, 68, 10%);
  }
`;

export const ButtonS = styled(BaseButton)`
  height: 80%;
  min-width: 2em;
  line-height: 0.9em;
  font-size: 0.9em;
  border-radius: 0.2em;
  color: ${Color.White};
  background-color: ${Color.DimGray}; 
  &:hover {
    color: ${Color.White};
    background-color: ${Color.DarkGray};
  }
  &:active {
    transform: translateY(2px);
    box-shadow: 0 0 1px rgba(68, 68, 68, 10%);
  }
`;

export const IconButton = styled(BaseButton)`
  padding: 0;
  margin: 0;
  background-color:rgba(0,0,0,0);
  &:active {
    transform: translateY(1px);
    box-shadow: 0 0 1px rgba(68, 68, 68, 10%);
  }
`;


export const HeaderButton = styled(BaseButton)`
  height: 100%;
  min-width: 4.5em;
  line-height: 1.8em;
  font-size: 0.95em;
  border-radius: 0.2em;
  color: ${Color.White};
  background-color: ${Color.DarkGray}; 
  &:hover {
    color: ${Color.White};
    background-color: ${Color.DimGray};
  }
  &:active {
    transform: translateY(2px);
    box-shadow: 0 0 1px rgba(68, 68, 68, 10%);
  }
`;

export default Button;