import * as React from "react";

const ModelViewerComponent = props => {
  return (
    <model-viewer
      id="model-viewer"
      src={props.src}
      ios-src="sample/usdz/newModel.usdz"
      alt="sample"
      quick-look-browsers="safari chrome"
      camera-controls
      camera-orbit="0deg 75deg 200%"
      ar
      ar-scale="fixed"
      autoplay
      magic-leap
      max-field-of-view="120deg"
      interaction-prompt="none"
      shadow-intensity="0.7"
      style={{ width: "100%", height: "100%" }}
    >
      </model-viewer>
  );
};

export default ModelViewerComponent;