import { ModelActionType } from "../actions/modelAction";

export const initialState = {
  name: "",
  buffer: [],
  src: "",
  timeArray: [],
  currentTime: 0,
  isPlay: true,
}

const modelReducer = (state = initialState, action) => {
  switch (action.type) {
    case ModelActionType.LOAD:
      return { ...state, buffer: action.buffer, src: action.src, timeArray: action.timeArray };
    case ModelActionType.UPDATE_TIME:
      return { ...state, currentTime: action.currentTime }
    case ModelActionType.UPDATE_ISPLAY:
      return { ...state, isPlay: action.isPlay }
    case ModelActionType.SET_NAME:
      return { ...state, name: action.name }
    default:
      return state;
  }
}

export default modelReducer;