import React from 'react';
import styled from 'styled-components';

const Select = styled.select`
`;

const Option = styled.option`
`;

const OptionList = (props) => {
  return (
    props.options.map((option, index, _) => {
      if (props.values === undefined) {
        return (
          <Option key={index} value={option}>{option}</Option>
        )
      } else {
        return (
          <Option key={index} value={props.values[index]}>{option}</Option>
        )
      }
    })
  )
}

const InputSelect = (props) => {
  const { options, value, values } = props;
  return (
    <Select value={value} id={props.id} onChange={props.onChange} name={props.name}>
      <OptionList options={options} values={values} />
    </Select>
  );
}

export default InputSelect;