import styled from 'styled-components';

export const Wrap = styled.div`
  box-sizing: border-box;
  height: ${props => props.h ? props.h : "auto"};
  background-color: ${props => props.bgColor ? props.bgColor : "inherit"};
  width: ${props => props.w ? props.w : "100%"};
  margin: ${props => props.m ? props.m : 0};
  margin-bottom: ${props => props.mb ? props.mb : 0};
  margin-right: ${props => props.mr ? props.mr : 0};
  margin-left: ${props => props.ml ? props.ml : 0};
  padding: ${props => props.p ? props.p : 0};
  border: ${props => props.border ? props.border : "none"};
  border-color: ${props => props.bdColor ? props.bdColor : "inherit"};
`;

export const FlexWrap = styled(Wrap)`
  display: flex;
`;

export const CenterWrap = styled(Wrap)`
  display: flex;
  justify-content: center;
  align-items: center;
`;

export const RightWrap = styled(Wrap)`
  text-align: right;
`;

export const LeftWrap = styled(Wrap)`
  text-align: left;
`;

export const ScrollWrap = styled(Wrap)`
  overflow-y: scroll;

  &::-webkit-scrollbar {
    display: none;
  }
`

export default Wrap;