import React from "react";
import { CenterWrap, LeftWrap, RightWrap } from "../atoms/Wrap";
import Label from "../atoms/Label";
import Color from "../../my_modules/Color";
import Link from "../atoms/Link";
import Menu from '@material-ui/core/Menu';
import MenuItem from '@material-ui/core/MenuItem';
import { HeaderButton } from '../atoms/Button';

const Header = () => {
  const [anchorEl, setAnchorEl] = React.useState(null);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  return (
    <CenterWrap bgColor={Color.DarkGray} h="100%" p="0 10px">
      <LeftWrap w="auto">
        <Label fs="20px" color={Color.White}>
          glMode.js
      </Label>
      </LeftWrap>

      <RightWrap >
        <HeaderButton onClick={handleClick}>
          アンケートにご協力ください
        </HeaderButton>
        <Menu
          id="simple-menu"
          anchorEl={anchorEl}
          keepMounted
          open={Boolean(anchorEl)}
          onClose={handleClose}
        >
          <MenuItem onClick={handleClose}>
            <Link
              fs="14px"
              mr="5px"
              color={Color.Black}
              href="https://docs.google.com/forms/d/e/1FAIpQLScfYosfMB4huPZFGdHqsmcmEj-rKNGNYOadSqJ1S8TZ0cZzgg/viewform?usp=sf_link">
              使いやすさアンケート(3分程度)
          </Link>
          </MenuItem>
          <MenuItem onClick={handleClose}>
            <Link
              fs="14px"
              color={Color.Black}
              href="https://docs.google.com/forms/d/e/1FAIpQLSdU90im2b9MTvZoM2bRroYmAmOvENa3rFEHGbgKo0pAbbcUfA/viewform?usp=sf_link">
              負担度アンケート(5分程度)
            </Link>
          </MenuItem>
        </Menu>
      </RightWrap>
    </CenterWrap>
  );
};

export default Header;