import React from "react";
import Wrap, { FlexWrap } from "../atoms/Wrap";
import Seekbar from "../atoms/Seekbar";
import Button from "../atoms/Button";
import Label from "../atoms/Label";

const ViewerMenuComponent = props => {
  // const arHref = "intent://arvr.google.com/scene-viewer/1.0?file=" + props.src + "&mode=ar_only#Intent;scheme=https;package=com.google.ar.core;action=android.intent.action.VIEW;S.browser_fallback_url=https://developers.google.com/ar;end;"
  // const src = "HSR.glb"
  // const arHref = "intent://arvr.google.com/scene-viewer/1.0?file=" + src + "#Intent;scheme=https;package=com.google.android.googlequicksearchbox;action=android.intent.action.VIEW;S.browser_fallback_url=https://developers.google.com/ar;end;"

  return (
    <Wrap>
      <Wrap mb="4px">
        <Seekbar
          value={props.currentTime}
          min={props.timeArray[0]}
          max={props.timeArray[props.timeArray.length - 1]}
          step={0.00001}
          onChange={props.onChangeSeekbar}
        />
      </Wrap>
      <FlexWrap>
        <Wrap w="auto" mr="5px">
          <Button onClick={props.onClickPlay}>PLAY</Button>
        </Wrap>
        <Wrap w="auto" mr="5px">
          <Button onClick={props.onClickPause}>PAUSE</Button>
        </Wrap>

        <Wrap w="auto" ml="auto">
          <Button onClick={props.onSaveModel}>EXPORT</Button>
        </Wrap>
      </FlexWrap>
    </Wrap>
  );
};

export default ViewerMenuComponent;