import React from "react";
import styled from 'styled-components';
import ViewerHeader from "../molecules/ViewerHeader";
import ModelViewer from "../atoms/ModelViewer";
import ViewerMenu from "../molecules/ViewerMenu";
import Wrap, { CenterWrap, FlexWrap } from "../atoms/Wrap";
import Color from "../../my_modules/Color";
import { InputFileButtonMat } from "../atoms/InputFileButton";
import Label from "../atoms/Label";

const LabelWrap = styled(CenterWrap)`
  justify-content: start;
  margin-left: 5px;
`;

const ViewerComponent = props => {
  return (
    <Wrap bgcolor={Color.White} h="100%" p="0 3px 0 3px">

      {/* Viewer Head */}
      <CenterWrap h="35px">
        <ViewerHeader onLoadFile={props.onLoadFile} glbName={props.glbName} />
      </CenterWrap>

      {/* time serial data/ */}
      <CenterWrap h="35px">
        <FlexWrap>
          <InputFileButtonMat type='file' text="Time-Series Data" onChange={e => props.onLoadMat(e)} />
          <LabelWrap>
            <Label fs="20px">{props.inputName}</Label>
          </LabelWrap>
        </FlexWrap>
      </CenterWrap>

      {/* Canvas Area */}
      <Wrap h="calc(100% - 130px)">
        {/* <Babylon src={props.src} /> */}
        <ModelViewer src={props.src} />
      </Wrap>

      {/* Viewer Menu */}
      <Wrap h="60px">
        <ViewerMenu
          timeArray={props.timeArray}
          currentTime={props.currentTime}
          onChangeSeekbar={props.onChangeSeekbar}
          onClickPlay={props.onClickPlay}
          onClickPause={props.onClickPause}
          onSaveModel={props.onSaveModel}
          src={props.src}
        />
      </Wrap>
    </Wrap>
  );
};

export default ViewerComponent;
