export const ModelActionType = {
  LOAD: "LOAD_MODEL",
  UPDATE_TIME: "UPDATE_TIME",
  UPDATE_ISPLAY: "UPDATE_ISPLAY",
  SET_NAME: "SET_NAME"
}

export const loadModel = (buffer, src, timeArray) => {
  return {
    type: ModelActionType.LOAD,
    buffer: buffer,
    src: src,
    timeArray: timeArray,
  }
}

export const updateTime = (currentTime) => {
  return {
    type: ModelActionType.UPDATE_TIME,
    currentTime: currentTime
  }
}

export const updateIsPlay = (isPlay) => {
  return {
    type: ModelActionType.UPDATE_ISPLAY,
    isPlay: isPlay
  }
}

export const setName = (fileName) => {
  return {
    type: ModelActionType.SET_NAME,
    name: fileName
  }
}