export const getArray = (matStr) => {
  const dataBeginPoint = 3;
  const keyframeCount = 300;

  const matArray = changeMatStringToArray(matStr);
  const matColumnQty = matArray[1];
  const allRowDataArray = getRowDataArray(matArray.slice(dataBeginPoint, matArray.length - 1), matColumnQty);
  const rowDataArray = divideArrIntoCount(allRowDataArray, keyframeCount);
  let columnDataArray = changeRowToColumnArray(rowDataArray, matColumnQty);
  columnDataArray = arrayParseFloat(columnDataArray);
  return columnDataArray;
}

const arrayParseFloat = (array) => {
  for (let i = 0; i < array.length; i++) {
    array[i] = array[i].map(str => parseFloat(str, 10));
  }
  return array;
}

const changeMatStringToArray = (matStr) => {
  matStr = matStr.replace(/\n/g, ' ').replace(/\s+/g, ' ');
  return matStr.split(' ');
};

const changeRowToColumnArray = (rowDataArray, matColumnQty) => {
  //列ごとのデータ配列の初期化
  let columnArray = [];
  for (let i = 0; i < matColumnQty; i++) {
    columnArray[i] = [];
  }

  //列ごとのデータ配列を作成
  for (let i = 0; i < rowDataArray.length; i++) {
    for (let j = 0; j < matColumnQty; j++) {
      columnArray[j][i] = rowDataArray[i][j];
    }
  }
  return columnArray;
}

const getRowDataArray = (matArray, matColumnQty) => {
  const allRowDataArray = divideArrIntoPieces(matArray, matColumnQty);
  return allRowDataArray;
}

const divideArrIntoPieces = (arr, n) => {
  const arrList = [];
  let idx = 0;
  while (idx < arr.length) {
    arrList.push(arr.slice(idx, idx + Number(n)));
    idx += Number(n);
  }
  return arrList;
}

const divideArrIntoCount = (allRowDataArray, almostKeyframeCount) => {
  const unitArray = Math.floor(allRowDataArray.length / almostKeyframeCount);

  const dataUnitRowArray = [];
  for (let i = 0; i < allRowDataArray.length; i++) {
    if (i % unitArray === 0) {
      dataUnitRowArray.push(allRowDataArray[i]);
    }
  }
  return dataUnitRowArray;
}