import { AnimationActionType } from "../actions/animationAction";

export const animationInfoForm = {
  translation: {
    x: 0,
    y: 0,
    z: 0,
  },
  rotation: {
    axis: "x",
    theta: 0,
  }
}

export const defaultState = {
  menus: [
    {
      id: 0,
      type: "translation",
      node: 1,
      time: {
        start: 0,
        end: 0,
      },
      animationInfo: animationInfoForm.translation,
    }
  ],
  node: {
    options: [],
    values: []
  },
  type: {
    options: ["translation", "rotation"],
    values: ["translation", "rotation"],
  },
  mode: "default",
}

export const initialState = {
  menus: [],
  type: {
    options: [],
    values: []
  },
  node: {
    options: [],
    values: []
  },
  inputName: "",
  inputArray: [],
  mode: "default",
}

const animationReducer = (state = initialState, action) => {
  switch (action.type) {
    case AnimationActionType.UPDATE_MENU:
      return { ...state, menus: action.menus };
    case AnimationActionType.SET_TYPE:
      return { ...state, type: action.cardType };
    case AnimationActionType.SET_NODE:
      return { ...state, node: action.node };
    case AnimationActionType.SET_ARRAY:
      return { ...state, inputArray: action.input };
    case AnimationActionType.SET_INPUT_NAME:
      return { ...state, inputName: action.name };
    case AnimationActionType.UPDATE_MODE:
      return { ...state, mode: action.mode };
    default:
      return state;
  }
}

export default animationReducer;