import React, { useState } from "react";
import EventListener from 'react-event-listener';
import Viewer from "../../containers/organisms/Viewer";
import Header from "../../containers/organisms/Header";
import AnimationMenu from "../../containers/organisms/AnimationMenu";
import Wrap, { FlexWrap } from "../atoms/Wrap";


const HomeComponent = () => {
  const [windowWidth, setWindowWidth] = useState(window.innerWidth)


  const handleResize = () => {
    setWindowWidth(window.innerWidth);
  }


  if (windowWidth > 600) {
    return (
      <>
        <EventListener target="window" onResize={handleResize} />
        <Wrap h="100%">
          <Wrap h="40px">
            <Header />
          </Wrap>

          {/* main content */}
          <FlexWrap h="calc(100% - 40px)">

            {/* Viewer */}
            <Wrap>
              <Viewer />
            </Wrap>

            {/* Animation Menu */}
            <Wrap>
              <AnimationMenu />
            </Wrap>
          </FlexWrap>
        </Wrap>
      </>
    )
  } else {
    return (
      <>
        <EventListener target="window" onResize={handleResize} />
        <Wrap h="100%">
          <Wrap h="40px">
            <Header />
          </Wrap>

          {/* main content */}
          <Wrap h="calc(100% - 40px)">

            {/* Viewer */}
            <Wrap w="100%" h="calc(100% - 40px)">
              <Viewer />
            </Wrap>

            {/* Animation Menu */}
            <Wrap w="100%" h="calc(100% - 40px)">
              <AnimationMenu />
            </Wrap>
          </Wrap>
        </Wrap>
      </>
    );
  }
};

export default HomeComponent;
