import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { loadModel, updateTime, updateIsPlay, setName } from "../../actions/modelAction";
import { updateMenu, setType, setNode, setInputName, setInputArray } from "../../actions/animationAction";
import { defaultState, animationInfoForm } from "../../reducers/animationReducer";
import * as mat from "../../my_modules/Mat";
import ViewerComponent from "../../components/organisms/Viewer";
import GLB from "../../my_modules/Glb";
import * as u from "../../my_modules/Utility";

export const makeGlbState = (glb) => {
  // model stateに関する設定
  const defaultAnimationNumber = 0;
  const timeArray = glb.getAnimationTimeArray(defaultAnimationNumber);
  const extras = glb.getExtras();
  if(extras == undefined){
    // animation stateに関する設定
    const target = glb.getAnimationTargets(defaultAnimationNumber);
    let nodeNames = glb.getNodeNameExceptMesh();
    nodeNames = nodeNames.map((node) => {
      return {
        id: node.id, name: u.takeStringLastPeriod(node.name)
      }
    })
    const menus = target.nodes.map((node, idx) => {
      const type = target.pathes[idx];
      const mode = defaultState.menus[0].mode;

      let animationInfo = "";
      switch (type) {
        case "translation":
          animationInfo = animationInfoForm.translation;
          break;
        case "rotation":
          animationInfo = animationInfoForm.rotation;
          break;
        default:
          animationInfo = undefined
          break;
      }

      const menu = {
        id: idx,
        type: type,
        node: node,
        time: {
          start: 0,
          end: 0
        },
        mode: mode,
        animationInfo: animationInfo
      }

      return menu;
    })

    const nodeOptions = nodeNames.map((node => { return node.name }));
    const nodeValues = nodeNames.map((node => { return node.id }));

    const type = {
      options: defaultState.type.options,
      values: defaultState.type.values
    }

    const node = {
      options: nodeOptions,
      values: nodeValues,
    }

    return { timeArray: timeArray, menus: menus, type: type, node: node };
  }else{
    // animation stateに関する設定
    const target = glb.getAnimationTargets(defaultAnimationNumber);
    let nodeNames = glb.getNodeNameExceptMesh();
    nodeNames = nodeNames.map((node) => {
      return {
        id: node.id, name: u.takeStringLastPeriod(node.name)
      }
    })

    const menus = extras['GLMODE_JS'].map((menu) =>{
      // let animationInfo = "";
      return menu;
    })
    const nodeOptions = nodeNames.map((node => { return node.name }));
    const nodeValues = nodeNames.map((node => { return node.id }));

    const type = {
      options: defaultState.type.options,
      values: defaultState.type.values
    }

    const node = {
      options: nodeOptions,
      values: nodeValues,
    }
    return { timeArray: timeArray, menus: menus, type: type, node: node };
  }
}

// GLBファイル読み込みに関する機能
const useLoadGLBModelFile = () => {
  const dispatch = useDispatch();

  const onLoadFile = event => {
    const file = event.target.files[0];
    const reader = new FileReader();

    reader.onload = e => {
      try {
        const arrayBuffer = e.target.result;
        const glb = new GLB(arrayBuffer);
        const state = makeGlbState(glb);
        // dipath model reducer
        dispatch(loadModel(glb.buffer, glb.src, state.timeArray));
        // dispath animation reducer
        dispatch(updateMenu(state.menus));
        dispatch(setType(state.type));
        dispatch(setNode(state.node));
      } catch (e) {
        console.log(e.message);
      }
    };

    if (file) {
      const fileName = event.target.files.item(0).name;
      if (fileName.match(/.(glb)$/i)) {
        reader.readAsArrayBuffer(file);
        dispatch(setName(fileName));
      } else {
        alert("Unsupported file");
      }
    }
  };

  return onLoadFile;
};

// seekbarに関する機能
const useChangeSeekbar = () => {
  const dispatch = useDispatch();
  const isPlay = useSelector(state => state.model.isPlay);

  const onSeekbarChange = event => {
    const currentTime = event.target.value;

    const model = document.getElementById("model-viewer");
    model.currentTime = currentTime;
    model.play();

    // animationの再生が停止状態ならpauseする
    if (isPlay === false) model.pause();

    dispatch(updateTime(currentTime));
  }

  useEffect(() => {
    const updateSeekbar = () => {
      const model = document.getElementById("model-viewer");

      // // stateがundefinedにならないようにcurrentTimeが取れなければ0をいれる
      // const currentTime = model.currentTime !== undefined
      //   ? model.currentTime
      //   : 0

      // dispatch(updateTime(currentTime));
    }

    const interval = setInterval(updateSeekbar, 30);

    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return onSeekbarChange;
}

// 再生ボタンや停止ボタンに関する機能
const useClickViewerMenuButton = () => {
  const dispach = useDispatch();

  const onClickPlay = () => {
    try {
      const model = document.getElementById("model-viewer");
      model.play();
      dispach(updateIsPlay(true));
    } catch (e) {
      console.log(e.message);
    }
  }

  const onClickPause = () => {
    try {
      const model = document.getElementById("model-viewer");
      model.pause();
      dispach(updateIsPlay(false));
    } catch (e) {
      console.log(e.message);
    }
  }

  return [onClickPlay, onClickPause]
};

const useSaveModel = () => {
  const buffer = useSelector(state => state.model.buffer);

  const onSaveModel = () => {
    if (buffer.length !== 0) {
      try {
        let a = document.createElement("a");
        document.body.appendChild(a);
        a.style = "display: none";

        // //ArrayBufferをBlobに変換                                                                                                                                                
        const blob = new Blob([buffer], { type: "octet/stream" }),
          url = window.URL.createObjectURL(blob);
        a.href = url;

        a.download = "newModel.glb";
        a.click();
        window.URL.revokeObjectURL(url);
      } catch (e) {
        console.log(e.message);
      }
    }
  }

  return onSaveModel;
}

const useLoadMat = () => {
  const dispatch = useDispatch();

  const onLoadMat = e => {
    const reader = new FileReader();

    //読み込み成功時のイベントを設定
    reader.onload = function (e) {
      const fileStr = e.target.result;
      const matArray = mat.getArray(fileStr);
      let iniArray = [];
      for (let i = 0; i < matArray[0].length; i++) {
        iniArray[i] = 0;
      }
      const stateArray = [iniArray].concat(matArray);
      dispatch(setInputArray(stateArray));
    }

    //読み込みが成功した際にデータのタイプを設定
    if (e.target.files.item(0).name && e.target.files) {
      const fileName = e.target.files.item(0).name;
      if (fileName.match(/.(mat)$/i)) {
        dispatch(setInputName(fileName));
        reader.readAsText(e.target.files[0]);
      } else {
        alert("Unsupported file");
      }
    }
  };

  return onLoadMat;
};

const ViewerContainer = () => {
  const onLoadFile = useLoadGLBModelFile();
  const onChangeSeekbar = useChangeSeekbar();
  const [onClickPlay, onClickPause] = useClickViewerMenuButton();
  const onSaveModel = useSaveModel();
  const onLoadMat = useLoadMat();

  // stateを読み込む
  const src = useSelector(state => state.model.src);
  const timeArray = useSelector(state => state.model.timeArray);
  const currentTime = useSelector(state => state.model.currentTime);
  const glbName = useSelector(state => state.model.name);
  const inputName = useSelector(state => state.animation.inputName)

  return (
    <ViewerComponent
      src={src}
      glbName={glbName}
      timeArray={timeArray}
      currentTime={currentTime}
      inputName={inputName}
      onLoadFile={onLoadFile}
      onClickPlay={onClickPlay}
      onClickPause={onClickPause}
      onChangeSeekbar={onChangeSeekbar}
      onSaveModel={onSaveModel}
      onLoadMat={onLoadMat}
    />
  );
};

export default ViewerContainer;