import React from "react";
import Wrap, { ScrollWrap, CenterWrap, FlexWrap } from "../atoms/Wrap";
import Label from "../atoms/Label";
import Color from "../../my_modules/Color";
import AnimationCard from "../molecules/AnimationCard";
import Button, { IconButton } from "../atoms/Button";
import AddIcon from '@material-ui/icons/Add';

const AnimationMenuComponent = props => {
  // AnimationCardの一覧
  const AnimationCardList = props.menus.map((menu) => {
    return (
      <AnimationCard
        key={menu.id}
        menu={menu}
        type={props.type}
        node={props.node}
        inputNames={props.inputNames}
        inputIdx={props.inputIdx}
        inputArray={props.inputArray}
        mode={props.mode}
        onChangeType={props.onChangeType}
        onChangeNode={props.onChangeNode}
        onChangeTime={props.onChangeTime}
        onChangeAxis={props.onChangeAxis}
        onChangeXYZ={props.onChangeXYZ}
        onChangeTheta={props.onChangeTheta}
        onClickDelete={props.onClickDelete}
        onClickMode={props.onClickMode}
        onChangeTimeMat={props.onChangeTimeMat}
        onChangeXYZMat={props.onChangeXYZMat}
        onChangeThetaMat={props.onChangeThetaMat}
        onClickAddAnimation={props.onClickAddAnimation}
      />
    )
  })

  // AnimationMenuComponent本体
  return (
    <ScrollWrap h="100%" p="4px" bgColor={Color.LightGray}>
      <FlexWrap>
        <Label fs="20px" mr="10px">Motion List</Label>
      </FlexWrap>
      <Wrap>
        {AnimationCardList}
      </Wrap>
      <CenterWrap>
        <IconButton onClick={props.onClickAddMenu}>
          <AddIcon />
        </IconButton>
      </CenterWrap>
      <CenterWrap>
        <Button onClick={props.onClickAddAnimation}>Update Animation</Button>
      </CenterWrap>
    </ScrollWrap>
  );
};

export default AnimationMenuComponent;