import React from "react";
import styled from 'styled-components';
import InputFileButton from "../atoms/InputFileButton";
import { FlexWrap, CenterWrap } from "../atoms/Wrap";
import Label from "../atoms/Label";

const LabelWrap = styled(CenterWrap)`
  justify-content: start;
  margin-left: 5px;
`
const ViewerHeaderComponent = props => {
  return (
    <FlexWrap>
      <InputFileButton type='file' onChange={e => props.onLoadFile(e)} text="FILE" />
      <LabelWrap>
        <Label fs="20px">{props.glbName}</Label>
      </LabelWrap>
    </FlexWrap>
  );
};

export default ViewerHeaderComponent;