import styled from 'styled-components';
import Color from '../../my_modules/Color';

export const InputText = styled.input.attrs({
  type: 'text',
})`
  width: 100%;
  border:0;
  padding:1px;
  font-size:1em;
  color: ${Color.DarkGray};
  border:solid 1px #ccc;
  box-sizing: border-box;
  cursor: pointer;
`;

export default InputText;
