import React from "react";
import styled from 'styled-components';
import Wrap, { FlexWrap, RightWrap, CenterWrap } from "../atoms/Wrap";
import Label from "../atoms/Label";
import SelectList from "../atoms/SelectList";
import InputText from "../atoms/InputText";
import RadioButton from "../atoms/RadioButton";
import Color from "../../my_modules/Color";
import HighlightOffIcon from '@material-ui/icons/HighlightOff';
import { IconButton, ButtonS } from "../atoms/Button";

const CardLabel = styled(Label)`
  margin-right:2px;
  font-size:16px;
`
const CardInputText = styled(InputText)`
  width: 60%;
`

const CardTimeText = styled(InputText)`
  width: 30px;
  width: 60px;
`

const ContentWrap = styled(FlexWrap)`
  margin-bottom: 2px;
  justify-content: flex-start;
`

const ModeWrap = styled(CenterWrap)`
  margin-left: 4px;
  justify-content: start;
`

const AnimationCardComponent = props => {
  let animationMenu = "";
  switch (props.menu.type) {
    case "translation":
      animationMenu =
        <>
          <ContentWrap>
            <CardLabel>X:</CardLabel>
            <CardInputText id={props.menu.id + "x"} name="x" onChange={props.onChangeXYZ} value={props.menu.animationInfo.x} />
          </ContentWrap>
          <ContentWrap>
            <CardLabel>Y:</CardLabel>
            <CardInputText id={props.menu.id + "y"} name="y" onChange={props.onChangeXYZ} value={props.menu.animationInfo.y} />
          </ContentWrap>
          <ContentWrap>
            <CardLabel>Z:</CardLabel>
            <CardInputText id={props.menu.id + "z"} name="z" onChange={props.onChangeXYZ} value={props.menu.animationInfo.z} />
          </ContentWrap>
        </>
      break;
    case "rotation":
      animationMenu =
        <>
          <ContentWrap>
            <CardLabel>Axis:</CardLabel>
            <RadioButton id={props.menu.id + "x"} name={props.menu.id + "axis"} value="x" checked={props.menu.animationInfo.axis === "x"} onChange={props.onChangeAxis} />
            <Label>X</Label>
            <RadioButton id={props.menu.id + "y"} name={props.menu.id + "axis"} value="y" checked={props.menu.animationInfo.axis === "y"} onChange={props.onChangeAxis} />
            <Label>Y</Label>
            <RadioButton id={props.menu.id + "z"} name={props.menu.id + "axis"} value="z" checked={props.menu.animationInfo.axis === "z"} onChange={props.onChangeAxis} />
            <Label>Z</Label>
          </ContentWrap>
          <ContentWrap>
            <CardLabel>Theta</CardLabel>
            <CardInputText id={props.menu.id + "theta"} value={props.menu.animationInfo.theta} onChange={props.onChangeTheta} />
          </ContentWrap>
        </>
      break;
    default:
      animationMenu =
        <ContentWrap>
          <CardLabel>NO TYPE</CardLabel>
        </ContentWrap>
      break;
  }

  let matAnimationMenu = "";

  if (props.mode === "mat") {
    switch (props.menu.type) {
      case "translation":
        matAnimationMenu =
          <>
            <ContentWrap>
              <CardLabel>X:</CardLabel>
              <Wrap w="auto">
                <SelectList
                  id={props.menu.id}
                  name="x"
                  options={props.inputNames}
                  values={props.inputIdx}
                  onChange={props.onChangeXYZMat}
                  value={props.menu.animationInfo.x}
                />
              </Wrap>
            </ContentWrap>
            <ContentWrap>
              <CardLabel>Y:</CardLabel>
              <Wrap w="auto">
                <SelectList
                  id={props.menu.id}
                  name="y"
                  options={props.inputNames}
                  values={props.inputIdx}
                  onChange={props.onChangeXYZMat}
                  value={props.menu.animationInfo.y}
                />
              </Wrap>
            </ContentWrap>
            <ContentWrap>
              <CardLabel>Z:</CardLabel>
              <Wrap w="auto">
                <SelectList
                  id={props.menu.id}
                  name="z"
                  options={props.inputNames}
                  values={props.inputIdx}
                  onChange={props.onChangeXYZMat}
                  value={props.menu.animationInfo.z}
                />
              </Wrap>
            </ContentWrap>
          </>
        break;
      case "rotation":
        matAnimationMenu =
          <>
            <ContentWrap>
              <CardLabel>Axis:</CardLabel>
              <RadioButton id={props.menu.id + "x"} name={props.menu.id + "axis"} value="x" checked={props.menu.animationInfo.axis === "x"} onChange={props.onChangeAxis} />
              <Label>X</Label>
              <RadioButton id={props.menu.id + "y"} name={props.menu.id + "axis"} value="y" checked={props.menu.animationInfo.axis === "y"} onChange={props.onChangeAxis} />
              <Label>Y</Label>
              <RadioButton id={props.menu.id + "z"} name={props.menu.id + "axis"} value="z" checked={props.menu.animationInfo.axis === "z"} onChange={props.onChangeAxis} />
              <Label>Z</Label>
            </ContentWrap>
            <ContentWrap>
              <CardLabel>Theta</CardLabel>
              <Wrap w="auto">
                <SelectList
                  id={props.menu.id}
                  options={props.inputNames}
                  values={props.inputIdx}
                  onChange={props.onChangeThetaMat}
                  value={props.menu.animationInfo.theta}
                />
              </Wrap>
            </ContentWrap>
          </>
        break;
      default:
        matAnimationMenu =
          <ContentWrap>
            <CardLabel>NO TYPE</CardLabel>
          </ContentWrap>
        break;
    }
  }

  let ModeButton = "";
  switch (props.mode) {
    case "default":
      if (props.inputArray.length !== 0) {
        ModeButton = <ButtonS id={props.menu.id + "mode"} name="default" onClick={props.onClickMode}>Time Expression</ButtonS>
      };
      break;
    case "mat":
      ModeButton = <ButtonS id={props.menu.id + "mode"} name="mat" onClick={props.onClickMode}>Time-Series Data</ButtonS>
      break;
    default:
      break;
  }

  switch (props.mode) {
    case "default":
      return (
        <Wrap mb="5px" p="3px" bgColor={Color.White} border="1px solid" bdColor={Color.Gray}>
          {/* node menu */}
          <ContentWrap>
            <CardLabel>node:</CardLabel>
            <Wrap w="auto">
              <SelectList
                id={props.menu.id}
                options={props.node.options}
                values={props.node.values}
                onChange={props.onChangeNode}
                value={props.menu.node}
              />
            </Wrap>
            <ModeWrap>
              {ModeButton}
            </ModeWrap>
            {/* <RightWrap w="auto">
              <ButtonS onClick={props.onClickAddAnimation}>Demo</ButtonS>
            </RightWrap> */}
            <RightWrap w="auto">
              <IconButton id={props.menu.id} onClick={props.onClickDelete}>
                <HighlightOffIcon style={{ pointerEvents: "none" }} color="error" fontSize="small" />
              </IconButton>
            </RightWrap>
          </ContentWrap>

          {/* type menu */}
          <ContentWrap>
            <CardLabel>type:</CardLabel>
            <Wrap w="auto">
              <SelectList
                id={props.menu.id}
                options={props.type.options}
                values={props.type.values}
                onChange={props.onChangeType}
                value={props.menu.type}
              />
            </Wrap>
          </ContentWrap>

          {/* node menu */}
          <ContentWrap mb="2px">
            <CardLabel>time:</CardLabel>
            <Wrap w="auto">
              <CardTimeText id={props.menu.id + "start"} name="start" onChange={props.onChangeTime} value={props.menu.time.start} />
              <Label> ~ </Label>
              <CardTimeText id={props.menu.id + "end"} name="end" onChange={props.onChangeTime} value={props.menu.time.end} />
            </Wrap>
          </ContentWrap>

          {animationMenu}
        </Wrap>
      );


    case "mat":
      return (
        <Wrap mb="5px" p="3px" bgColor={Color.White} border="1px solid" bdColor={Color.Gray}>
          {/* node menu */}
          <ContentWrap mb="2px">
            <CardLabel>node:</CardLabel>
            <Wrap w="auto">
              <SelectList
                id={props.menu.id}
                options={props.node.options}
                values={props.node.values}
                onChange={props.onChangeNode}
                value={props.menu.node}
              />
            </Wrap>
            <ModeWrap>
              {ModeButton}
            </ModeWrap>
            <RightWrap w="auto">
              <IconButton id={props.menu.id} onClick={props.onClickDelete}>
                <HighlightOffIcon style={{ pointerEvents: "none" }} color="error" fontSize="small" />
              </IconButton>
            </RightWrap>
          </ContentWrap>

          {/* type menu */}
          <ContentWrap mb="2px">
            <CardLabel>type:</CardLabel>
            <Wrap w="auto">
              <SelectList
                id={props.menu.id}
                options={props.type.options}
                values={props.type.values}
                onChange={props.onChangeType}
                value={props.menu.type}
              />
            </Wrap>
          </ContentWrap>

          {/* node menu */}
          <ContentWrap mb="2px">
            <CardLabel>time:</CardLabel>
            <Wrap w="auto">
              <SelectList
                id={props.menu.id}
                options={props.inputNames}
                values={props.inputIdx}
                onChange={props.onChangeTimeMat}
                value={props.time}
              />
            </Wrap>
          </ContentWrap>

          {matAnimationMenu}
        </Wrap>
      );
    default: break;
  }
};

export default AnimationCardComponent;