import { evaluate } from "mathjs";
import * as THREE from "three";

export default class Glb {
  #buffer = []; // 全体のbuffer
  #blob = new Blob();
  #eachArrayBuffer = [];
  #src = "";
  #indexOfJSON = 0; // 32bit区切りでJSON(1313821514)という文字列があるindex
  #indexOfBIN = 0; // 32bit区切でBIN(5130562)という文字列があるindex
  #chunk0 = {}; // chunk0のJSON部分のObject
  #chunk1 = {};// chunk1のBinaryBuffer部分
  #defaultAnimation = {}; // animations[0]
  #lastByte = 0; // file全体のlastbyte
  #componentType = 5126; // number of type of "Float"
  #keyframeCount = 300; // animation keyframe
  #interpolation = "LINEAR"; //animation[]['samplers'] interpolation

  #addAnimationTimeArrray = []; //addAnimationの計算用あんまりよくないので消したい

  constructor(arrayBuffer) {
    this.#loadFromBuffer(arrayBuffer);
  }

  addAnimation = (menus, inputArray, mode) => {
    const animationName = "add_animation";   
    const adjustedMenus = this.#adjustMenu(menus);
    const menuQty = this.#getMenusQty(adjustedMenus); // 重複メニューは一つとして数える
    const accessors = this.#createAccessor(adjustedMenus);
    const animations = this.#createAnimations(adjustedMenus, menuQty, animationName);
    const binaryBuffer = this.#createBinaryBuffer(adjustedMenus, inputArray, mode);
    const bufferViews = this.#createBufferViews(accessors, menuQty * 2);
    const extras = this.#createExtras(menus);

    this.#combineAccessors(accessors);
    this.#combineAnimations(animations);
    this.#combineBufferViews(bufferViews);
    this.#combineExtras(extras);
    this.#combineBinaryBuffer(binaryBuffer);
    this.#updateBuffers();

    const chunk0Buffer = this.#convertObjToBuffer(this.#chunk0);
    const chunk1Buffer = this.#chunk1;
    const chunk0HeaderBuffer = this.#createChunk0Header(chunk0Buffer.byteLength);
    const chunk1HeaderBuffer = this.#createChunk1Header(chunk1Buffer.byteLength);
    const headerBuffer = this.#createHeader(chunk0Buffer.byteLength, chunk1Buffer.byteLength);

    let allGlbDatas = [];
    allGlbDatas[0] = headerBuffer;
    allGlbDatas[1] = chunk0HeaderBuffer;
    allGlbDatas[2] = chunk0Buffer;
    allGlbDatas[3] = chunk1HeaderBuffer;
    allGlbDatas[4] = chunk1Buffer;

    // new GLB binary buffer
    const newBuffer = this.#concatenation(allGlbDatas);
    this.#loadFromBuffer(newBuffer);
  }

  getAnimationTimeArray = (animationNumber) => {
    let timeArray = [];
    if (this.#chunk0['animations'] !== undefined) {
      const timeAccessorNumber = this.#chunk0['animations'][animationNumber]['samplers'][0]['input'];
      const timeAccessor = this.#chunk0['accessors'][timeAccessorNumber];
      const timeBufferViewsNumber = timeAccessor['bufferView'];
      const timeBufferViews = this.#chunk0['bufferViews'][timeBufferViewsNumber];
      timeArray = this.#getFloatBuffer(this.#chunk1, timeBufferViews['byteOffset'], timeBufferViews['byteLength']);
    } else {
      timeArray = [0];
    }
    return timeArray;
  }

  getAnimationTargets = (animationNumber) => {
    let targets = { 'pathes': [], 'nodes': [] };
    if (this.#chunk0['animations'] !== undefined) {
      const targetAnimations = this.#chunk0['animations'][animationNumber];

      const nodes = targetAnimations['channels'].map((channnel) => {
        return channnel['target']['node'];
      })

      const pathes = targetAnimations['channels'].map((channel => {
        return channel['target']['path'];
      }))

      targets = { 'nodes': nodes, 'pathes': pathes, }
    } else {
      targets = undefined;
    }
    return targets;
  }

  getNodeNameExceptMesh = () => {
    const nodes = this.#chunk0['nodes'].map((node, idx) => {
      if (node['name'] === undefined && node['mesh'] === undefined) return { id: idx, name: idx }
      else if (node['mesh'] === undefined) return { id: idx, name: node['name'] }
      else return undefined;
    })
    return nodes.filter((node => {
      return node !== undefined;
    }))
  }

  getExtras = () => {
    return this.#chunk0['extras'];
  }

  /////////////////////////
  // private methods
  /////////////////////////
  #adjustMenu = (menus) => {
    // nodeごとにmenuをまとめる
    //
    // adjustedMenus = [
    //   {
    //     node: -1,
    //     translation:[menu1,menu2]
    //     rotation:[menu3,menu4]
    //   },
    // ]

    // 重複しているnodeをまとめる
    const nodes = (() => {
      let result = menus.map(menu => {
        return menu.node;
      })

      result = result.filter((x, i, self) => {
        return self.indexOf(x) === i;
      })
      return result;
    })();

    // adjusteMenusをつくる
    let adjustedMenus = nodes.map((node) => {
      return { "node": node, "translation": [], "rotation": [] }
    })
    menus.forEach(menu => {
      let nodeIdx;
      adjustedMenus.forEach((val, idx) => {
        if (val.node === menu.node) nodeIdx = idx;
      })
      switch (menu.type) {
        case "translation": adjustedMenus[nodeIdx].translation.push(menu);
          break;
        case "rotation": adjustedMenus[nodeIdx].rotation.push(menu);
          break;
        default: console.log("type error");
          break;
      }
    })
    return adjustedMenus;
  }

  #concatenation = (segments) => {
    var sumLength = 0;
    for (let i = 0; i < segments.length; ++i) {
      sumLength += segments[i].byteLength;
    }
    var whole = new Uint8Array(sumLength);
    var pos = 0;
    for (let i = 0; i < segments.length; ++i) {
      whole.set(new Uint8Array(segments[i]), pos);
      pos += segments[i].byteLength;
    }
    return whole.buffer;
  }

  #concatenationFloat32 = (segments) => {
    var sumLength = 0;
    for (let i = 0; i < segments.length; ++i) {
      sumLength += segments[i].byteLength;
    }

    let whole = new Float32Array(sumLength / 4);
    let pos = 0;
    for (let i = 0; i < segments.length; ++i) {
      whole.set(new Float32Array(segments[i]), pos);
      pos += segments[i].byteLength / 4;
    }
    return whole.buffer;
  }

  #convertObjToBuffer = (obj) => {
    let objText = JSON.stringify(obj);

    // adjust 4 byte multiple
    const objTextByte = encodeURIComponent(objText).replace(/%../g, "x").length;
    let emptyCount;
    switch (objTextByte % 4) {
      case 0: emptyCount = 0; break;
      case 1: emptyCount = 3; break;
      case 2: emptyCount = 2; break;
      case 3: emptyCount = 1; break;
      default: console.log("empty Error"); break;
    }
    let idx = 0;
    while (idx < emptyCount) {
      objText = objText + ' ';
      idx++;
    }

    return this.#stringToBuffer(objText);
  }

  #combineAccessors = (accessors) => {
    accessors.forEach((accessor) => {
      this.#chunk0['accessors'].push(accessor);
    })
  }

  #combineAnimations = (animations) => {
    if (this.#chunk0['animations'].length !== 0) {
      this.#chunk0['animations'][0] = animations;
    } else {
      this.#chunk0['animations'] = [];
      this.#chunk0['animations'][0] = animations;
    }
  }

  #combineBufferViews = (bufferViews) => {
    bufferViews.forEach((bufferView) => {
      this.#chunk0['bufferViews'].push(bufferView);
    })
  }

  #combineBinaryBuffer = (binaryBuffer) => {
    let binaryBuffers = [];
    let binaryBuffersGlb = [];

    // Adjust original GLB to 4 bytes
    binaryBuffersGlb[0] = this.#chunk1;
    let emptyQty;
    switch (binaryBuffersGlb[0].byteLength % 4) {
      case 0: emptyQty = 0; break;
      case 1: emptyQty = 3; break;
      case 2: emptyQty = 2; break;
      case 3: emptyQty = 1; break;
      default: console.log("error empty"); break;
    }

    let emptyBuffer = new ArrayBuffer(emptyQty);
    let dv = new DataView(emptyBuffer);
    for (let i = 0; i < emptyQty; i++) {
      dv.setUint8(i, ' ', true);
    }
    binaryBuffersGlb[1] = emptyBuffer;
    binaryBuffers[0] = this.#concatenation(binaryBuffersGlb)

    // combine original & new glb
    binaryBuffers[1] = binaryBuffer;
    let combinedBinaryBuffer = this.#concatenationFloat32(binaryBuffers);

    // set state
    this.#chunk1 = combinedBinaryBuffer;
  }

  #combineExtras =(extras) =>{
    this.#chunk0['extras'] = extras[0];
  }

  #createAnimations = (adjustedMenus, menuQty, name) => {
    // 重複ノードを合わせたnodeの配列
    const targetNodes = adjustedMenus.map((menu) => {
      return menu.node;
    })

    // 重複pathをまとめたpatheの配列
    const targetPathes = adjustedMenus.map((menu) => {
      const pathes = [];
      if (menu.translation.length !== 0) pathes.push("translation");
      if (menu.rotation.length !== 0) pathes.push("rotation");
      return pathes;
    });

    const channels = (() => {
      const channels = [];
      let count = 0;
      targetPathes.forEach((path, idx) => {
        path.forEach(val => {
          channels.push({
            "target": {
              "path": val,
              "node": Number(targetNodes[idx])
            },
            "sampler": count,
          })
          count++;
        })
      });
      return channels;
    })();

    const samplers = (() => {
      const lastAccessorNumber = this.#chunk0.accessors.length;
      const samplers = [];
      let idx = 0;
      let input = 0;
      let output = 1;
      while (idx < menuQty) {
        samplers.push({
          "interpolation": this.#interpolation,
          "input": lastAccessorNumber + input,
          "output": lastAccessorNumber + output,
        })
        input += 2;
        output += 2;
        idx += 1;
      }
      return samplers;
    })();

    const animations = {
      "name": name,
      "channels": channels,
      "samplers": samplers
    };

    return animations;
  }

  #createAccessor = (adjustedMenus) => {
    const lastBufferViewsNumber = this.#chunk0['bufferViews'].length;
    const accessors = [];
    let idx = 0;

    adjustedMenus.forEach(menu => {
      if (menu.translation.length !== 0) {
        // input (time)
        accessors.push({
          "componentType": this.#componentType,
          "count": this.#keyframeCount,
          "bufferView": lastBufferViewsNumber + idx,
          "type": 'SCALAR'
        })
        idx++;

        // output 
        accessors.push({
          "componentType": this.#componentType,
          "count": this.#keyframeCount,
          "bufferView": lastBufferViewsNumber + idx,
          "type": 'VEC3'
        })
        idx++;
      }

      if (menu.rotation.length !== 0) {
        // input (time)
        accessors.push({
          "componentType": this.#componentType,
          "count": this.#keyframeCount,
          "bufferView": lastBufferViewsNumber + idx,
          "type": 'SCALAR'
        })
        idx++;

        // output 
        accessors.push({
          "componentType": this.#componentType,
          "count": this.#keyframeCount,
          "bufferView": lastBufferViewsNumber + idx,
          "type": 'VEC4'
        })
        idx++;
      }
    });
    return accessors;
  };

  #createBinaryBuffer = (adjustedMenus, inputArray, mode) => {
    const entireTime = this.#getEntireTime(adjustedMenus, mode); // end時間の最大値

    const binaryBuffers = [];
    adjustedMenus.forEach(menu => {
      if (menu.translation.length !== 0) {
        binaryBuffers.push(this.#createTimeBuffer(entireTime, menu.translation, inputArray, mode));
        binaryBuffers.push(this.#createTranslationBuffer(menu.translation, entireTime, inputArray, mode));
      }
      if (menu.rotation.length !== 0) {
        binaryBuffers.push(this.#createTimeBuffer(entireTime, menu.rotation, inputArray, mode));
        binaryBuffers.push(this.#createRotationBuffer(menu.rotation, entireTime, inputArray, mode));
      }
    })

    let binaryBuffer = this.#concatenationFloat32(binaryBuffers);
    return binaryBuffer;
  }

  #createBufferViews = (accessors, bufferViewsQty) => {
    const bufferViews = [];

    // adjust emtpty 
    switch (this.#lastByte % 4) {
      case 0: this.#lastByte += 0; break;
      case 1: this.#lastByte += 3; break;
      case 2: this.#lastByte += 2; break;
      case 3: this.#lastByte += 1; break;
      default: console.log("empty error");
    }

    let idx = 0;
    while (idx < bufferViewsQty) {
      let columnQty = 0;
      switch (accessors[idx]["type"]) {
        case "SCALAR": columnQty = 1; break;
        case "VEC3": columnQty = 3; break;
        case "VEC4": columnQty = 4; break;
        default: console.log("no type erro (create buffer views)");
      }
      let byteLength = this.#keyframeCount * columnQty * 4;

      bufferViews.push(
        {
          "byteOffset": this.#lastByte,
          "byteLength": byteLength,
          "buffer": 0,
        }
      );

      this.#lastByte += byteLength; // update last byte
      idx++;
    }

    return bufferViews;
  }

  #createChunk0Header = (chunk0Length) => {
    let buffer = new ArrayBuffer(8);
    let view = new DataView(buffer);

    view.setUint32(0, chunk0Length, true);
    view.setUint32(4, 1313821514, true);

    return buffer;
  }

  #createChunk1Header = (chunk1Length) => {
    let buffer = new ArrayBuffer(8);
    let view = new DataView(buffer);

    view.setUint32(0, chunk1Length, true);
    view.setUint32(4, 5130562, true);

    return buffer;
  }

  #createExtras = (menus) => {
    const extras = [];
    extras.push(
      {'GLMODE_JS' : menus}
    );
    return extras;
  }

  #createHeader = (chunk0Length, chunk1Length) => {
    let buffer = new ArrayBuffer(12);
    let view = new DataView(buffer);

    view.setUint32(0, 1179937895, true);
    view.setUint32(4, 2, true);
    view.setUint32(8, chunk0Length + chunk1Length + 28, true);

    return buffer;
  }

  #createTimeBuffer = (entireTime, menu, inputArray, mode) => {
    let timeArray = [];
    let timeBuffer;

    if (mode === "default") {
      const unitTime = entireTime / this.#keyframeCount;
      for (let i = 0; i < this.#keyframeCount; i++) {
        timeArray[i] = unitTime * i;
      }

      timeBuffer = new ArrayBuffer(this.#keyframeCount * 4);
      let dv = new DataView(timeBuffer);

      for (let i = 0; i < timeArray.length; i++) {
        dv.setFloat32(4 * i, timeArray[i], true);
      }
    }

    if (mode === "mat") {
      timeArray = inputArray[menu[0].time];
      timeBuffer = new ArrayBuffer(timeArray.length * 4);
      let dv = new DataView(timeBuffer);
      for (let i = 0; i < timeArray.length; i++) {
        dv.setFloat32(4 * i, timeArray[i], true);
      }
    }

    this.#addAnimationTimeArrray = timeArray;
    return timeBuffer;
  }

  #createTranslationBuffer = (menus, entireTime, inputArray, mode) => {
    const times = menus.map((menu) => {
      return ([Number(menu.time.start), Number(menu.time.end)])
    })

    const animationInfo = menus.map((menu => {
      return ([menu.animationInfo.x, menu.animationInfo.y, menu.animationInfo.z]);
    }));

    const translationArray = animationInfo.map((eachAnimation, idx1) => {
      let eachTranslationArray = eachAnimation.map((value) => {
        let eachOfXYZ = [];
        switch (mode) {
          case "default":
            eachOfXYZ = this.#getTranslationArray(value, entireTime, times[idx1]);
            break;
          case "mat":
            eachOfXYZ = inputArray[value];
            this.#keyframeCount = eachOfXYZ.length;
            break;
          default: break;
        }
        return eachOfXYZ;
      });
      return eachTranslationArray;
    });
    let vec3Array = new Array(3);
    for (let i = 0; i < vec3Array.length; i++) {
      vec3Array[i] = [];
      for (let j = 0; j < this.#keyframeCount; j++) {
        vec3Array[i][j] = 0;
      }
    }

    for (let i = 0; i < translationArray.length; i++) {
      for (let j = 0; j < 3; j++) {
        for (let k = 0; k < this.#keyframeCount; k++) {
          vec3Array[j][k] += translationArray[i][j][k];
        }
      }
    }

    let vec3Buffer = new ArrayBuffer(this.#keyframeCount * 4 * 3);
    let dv = new DataView(vec3Buffer);

    for (let i = 0; i < vec3Array[0].length; i++) {
      dv.setFloat32(12 * i, vec3Array[0][i], true);
      dv.setFloat32(12 * i + 4, vec3Array[1][i], true);
      dv.setFloat32(12 * i + 8, vec3Array[2][i], true);
    }
    return vec3Buffer;
  }

  #createRotationBuffer = (menus, entireTime, inputArray, mode) => {
    const times = menus.map((menu) => {
      return ([Number(menu.time.start), Number(menu.time.end)])
    })

    const axises = menus.map((menu => {
      let axis = [];
      switch (menu.animationInfo.axis) {
        case "x":
          axis = [1, 0, 0];
          break;
        case "y":
          axis = [0, 1, 0];
          break;
        case "z":
          axis = [0, 0, 1];
          break
        default: break;
      }
      return new THREE.Vector3(axis[0], axis[1], axis[2]);
    }));

    const angles = menus.map((menu) => {
      return (menu.animationInfo.theta);
    });

    const angleArraies = angles.map((angle, idx) => {
      let angleArray;
      if (mode === "default") {
        angleArray = this.#getRotationArray(angle, times[idx], entireTime)
      }
      if (mode === "mat") {
        angleArray = inputArray[angle];
      }
      return angleArray
    })

    let tmpQ = [];

    let synthesisQuaternionArray = [];
    let idx = 0;
    while (idx < this.#keyframeCount) {
      if (angleArraies.length === 1) {
        tmpQ[0] = new THREE.Quaternion();
        synthesisQuaternionArray[idx] = tmpQ[0].setFromAxisAngle(axises[0], angleArraies[0][idx]);
        idx++;
      } else {
        for (let i = 0; i < angleArraies.length; i++) {
          tmpQ[i] = new THREE.Quaternion();
          tmpQ[i].setFromAxisAngle(axises[i], angleArraies[i][idx]);
        }
        let tmp;
        for (let i = 0; i < angleArraies.length; i++) {
          if (i === 0) {
            tmp = tmpQ[0]
          } else {
            tmp = tmp.multiply(tmpQ[i]);
          }
        }
        synthesisQuaternionArray[idx] = tmp;
        idx++;
      }
    }

    let vec4Buffer = new ArrayBuffer(this.#keyframeCount * 4 * 4);
    let dv = new DataView(vec4Buffer);
    for (let i = 0; i < this.#keyframeCount; i++) {
      dv.setFloat32(16 * i, synthesisQuaternionArray[i]['_x'], true);
      dv.setFloat32(16 * i + 4, synthesisQuaternionArray[i]['_y'], true);
      dv.setFloat32(16 * i + 8, synthesisQuaternionArray[i]['_z'], true);
      dv.setFloat32(16 * i + 12, synthesisQuaternionArray[i]['_w'], true);
    }
    return vec4Buffer;
  }

  #getEntireTime = (adjustedMenus, mode) => {
    let entireTime = 0;
    adjustedMenus.forEach(menu => {
      menu.rotation.forEach(rotation => {
        if (mode === "default") {
          if (entireTime < Number(rotation.time.end)) {
            entireTime = Number(rotation.time.end);
          }
        }
      })

      menu.translation.forEach(translation => {
        if (mode === "default") {
          if (entireTime < Number(translation.time.end)) {
            entireTime = Number(translation.time.end);
          }
        }
      })
    })

    return entireTime;
  }

  #getBlob = () => {
    return new Blob([this.#buffer], { type: "octet/stream" });
  }

  #getChunk0 = () => {
    const byteBegin = 4 * (this.#indexOfJSON + 1);
    const byteEnd = 4 * (this.#indexOfBIN - 1);
    const jsonArray = this.#eachArrayBuffer.uint8.slice(byteBegin, byteEnd);

    // 1024バイトごとにjson配列を切って、stringでくっつける
    const jsonStr = (() => {
      let str = "";
      for (let i = 0; i < jsonArray.length; i += 1024) {
        str += String.fromCharCode.apply(null, jsonArray.slice(i, i + 1024));
      }
      return str;
    })();

    return JSON.parse(jsonStr);
  }

  #getChunk1 = () => {
    const byteBegin = 4 * (this.#indexOfBIN + 1);
    const byteEnd = this.#eachArrayBuffer.uint8.length;
    return this.#buffer.slice(byteBegin, byteEnd);
  }

  #getDefaultAnimation = () => {
    const defaultAnimation = this.#chunk0['animations'] !== undefined
      ? this.#chunk0['animations'][0]
      : null
    return defaultAnimation;
  }

  #getEachArrayBuffer = () => {
    return {
      uint32: new Uint32Array(this.#buffer),
      uint8: new Uint8Array(this.#buffer),
      float32: new Float32Array(this.#buffer)
    };
  };

  #getFloatBuffer = (buffer, begin, length) => {
    const bufferFloat = new Float32Array(buffer);
    return bufferFloat.slice(begin / 4, (begin + length) / 4);
  }

  #getLastByte = () => {
    const bufferViews = this.#chunk0['bufferViews'];
    const lastBufferViewsNumber = bufferViews.length - 1;
    return bufferViews[lastBufferViewsNumber]['byteOffset'] + bufferViews[lastBufferViewsNumber]["byteLength"]
  }

  #getMenusQty = (adjustedMenus) => {
    let count = 0;
    adjustedMenus.forEach(menu => {
      if (menu.translation.length !== 0) count++;
      if (menu.rotation.length !== 0) count++;
    })
    return count;
  }

  #getRotationArray = (angle, time, entireTime) => {
    let rotationArray = [];
    const divideUnit = [];
    divideUnit.push(Math.round(this.#keyframeCount * (time[0] / entireTime)));
    divideUnit.push(Math.round(this.#keyframeCount * (time[1] / entireTime)));
    let valueCount = 0;
    if (angle === 0) { angle = "0" }

    for (let i = 0; i < this.#keyframeCount; i++) {
      if (divideUnit[0] <= i && i <= divideUnit[1]) {
        let t = Number(this.#addAnimationTimeArrray[valueCount]);
        let output = evaluate(angle.replace(/t/g, t));
        rotationArray[i] = output;
        valueCount++;
      } else if (divideUnit[0] > i) {
        rotationArray[i] = 0;
      } else {
        let t = Number(this.#addAnimationTimeArrray[valueCount]);
        let output = evaluate(angle.replace(/t/g, t));
        rotationArray[i] = output;
      }
    }
    return rotationArray;
  }

  #getSrc = () => {
    return window.URL.createObjectURL(this.#blob);
  };


  #getTranslationArray = (output, entireTime, time) => {
    let translationArray = [];
    const divideUnit = [];
    divideUnit.push(Math.round(this.#keyframeCount * (time[0] / entireTime)));
    divideUnit.push(Math.round(this.#keyframeCount * (time[1] / entireTime)));
    if (output === 0) { output = "0" }
    let valueCount = 0;
    for (let i = 0; i < this.#keyframeCount; i++) {
      if (divideUnit[0] <= i && i <= divideUnit[1]) {
        let t = Number(this.#addAnimationTimeArrray[valueCount]);
        translationArray[i] = evaluate(output.replace(/t/g, t));
        valueCount++;
      } else if (divideUnit[0] > i) {
        translationArray[i] = 0;
      } else {
        let t = Number(this.#addAnimationTimeArrray[valueCount]);
        translationArray[i] = evaluate(output.replace(/t/g, t));
      }
    }

    return translationArray;
  }

  #loadFromBuffer = arrayBuffer => {
    this.#buffer = arrayBuffer;
    this.#blob = this.#getBlob();
    this.#eachArrayBuffer = this.#getEachArrayBuffer();
    this.#src = this.#getSrc();
    this.#indexOfJSON = this.#eachArrayBuffer.uint32.indexOf(1313821514);
    this.#indexOfBIN = this.#eachArrayBuffer.uint32.indexOf(5130562);
    this.#chunk0 = this.#getChunk0();
    this.#chunk1 = this.#getChunk1();
    this.#defaultAnimation = this.#getDefaultAnimation();
    this.#lastByte = this.#getLastByte();
  }

  #stringToBuffer = (string) => {
    return (new Uint8Array([].map.call(string, function (c) {
      return c.charCodeAt(0)
    }))).buffer;
  }

  #updateBuffers = () => {
    this.#chunk0['buffers'][0]['byteLength'] = this.#lastByte;
  }

  ////////////////////////
  // getter
  ////////////////////////
  get buffer() {
    return this.#buffer;
  }

  get chunk0() {
    return this.#chunk0;
  }

  get chunk0Header() {
    return this.#eachArrayBuffer.uint32.slice(this.#indexOfJSON - 1, this.#indexOfJSON + 1);
  }

  get chunk1() {
    return this.#chunk1;
  }

  get chunk1Header() {
    return this.#eachArrayBuffer.uint32.slice(this.#indexOfBIN - 1, this.#indexOfBIN + 1);
  }

  get defaultAnimation() {
    return this.#defaultAnimation;
  }

  get src() {
    return this.#src;
  }
}