export const AnimationActionType = {
  UPDATE_MENU: "UPDATE_MENU",
  SET_TYPE: "SET_TYPE",
  SET_NODE: "SET_NODE",
  SET_INPUT_NAME: "SET_INPUT_NAME",
  SET_ARRAY: "SET_ARRAY",
  UPDATE_MODE: "UPDATE_MODE"
}

export const updateMenu = (menus) => {
  return {
    type: AnimationActionType.UPDATE_MENU,
    menus: menus
  }
}

// 引数のtypeはカードのタイプを指す
export const setType = (type) => {
  return {
    type: AnimationActionType.SET_TYPE,
    cardType: type
  }
}

export const setNode = (node) => {
  return {
    type: AnimationActionType.SET_NODE,
    node: node
  }
}

export const setInputName = (name) => {
  return {
    type: AnimationActionType.SET_INPUT_NAME,
    name: name,
  }
}

export const setInputArray = (input) => {
  return {
    type: AnimationActionType.SET_ARRAY,
    input: input
  }
}

export const updateMode = (mode) => {
  return {
    type: AnimationActionType.UPDATE_MODE,
    mode: mode
  }
}