// floatで指定範囲の値を取得する
export const getFloatBuffer = (buffer, begin, length) => {
  const bufferFloat = new Float32Array(buffer);
  return bufferFloat.slice(begin / 4, (begin + length) / 4);
}

//ラストピリオド以下の文字列を取得する
export const takeStringLastPeriod = (string) => {
  let pos = string.lastIndexOf('.');
  if (pos !== -1) string = string.slice(pos + 1);
  return string;
}