import React, { useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import AnimationMenuComponent from "../../components/organisms/AnimationMenu";
import { loadModel } from "../../actions/modelAction";
import { updateMenu, updateMode } from "../../actions/animationAction";
import { animationInfoForm, defaultState } from "../../reducers/animationReducer";
import GLB from "../../my_modules/Glb";
import { makeGlbState } from "./Viewer";

// typeの変更に関する機能
const useChangeType = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onChangeType = event => {
    const type = event.target.value;
    const menuId = Number(event.target.id);

    // typeを更新する
    menus = menus.map(menu => {
      if (menu.id === menuId) {
        delete menu.type;
        menu.type = type;
      }
      return menu;
    });

    // animationの入力情報を更新する
    switch (type) {
      case "translation":
        menus = menus.map(menu => {
          if (menu.id === menuId) {
            delete menu.animationInfo;
            menu.animationInfo = animationInfoForm.translation;
          }
          return menu;
        })
        break;
      case "rotation":
        menus = menus.map(menu => {
          if (menu.id === menuId) {
            delete menu.animationInfo;
            menu.animationInfo = animationInfoForm.rotation;
          }
          return menu;
        })
        break;
      default:
        console.log("error type");
        break;
    }

    dispatch(updateMenu(menus));
  }

  return onChangeType;
}

// nodeの変更に関する機能
const useChangeNode = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onChangeNode = event => {
    const node = Number(event.target.value);
    const menuId = Number(event.target.id);

    // menuのanimationInfo(axis)を更新する
    menus = menus.map(menu => {
      if (menu.id === menuId) {
        delete menu.node
        menu.node = node
      }
      return menu;
    });

    dispatch(updateMenu(menus));
  }

  return onChangeNode;
}

// rotation特有のmenuに関する機能
const useAxisTheta = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onChangeAxis = event => {
    const axis = event.target.value;
    const menuId = Number(event.target.id.replace(/[^0-9]/g, ''));

    // menuのanimationInfo(axis)を更新する
    menus = menus.map(menu => {
      if (menu.id === menuId) {
        const oldTheta = menu.animationInfo.theta;
        delete menu.animationInfo;
        menu.animationInfo = { axis: axis, theta: oldTheta }
      }
      return menu;
    });

    dispatch(updateMenu(menus));
  }

  const onChangeTheta = event => {
    const theta = event.target.value;
    const menuId = Number(event.target.id.replace(/[^0-9]/g, ''));

    // menuのanimationInfo(theta)を更新する
    menus = menus.map(menu => {
      if (menu.id === menuId) {
        const oldaxis = menu.animationInfo.axis;
        delete menu.animationInfo;
        menu.animationInfo = { axis: oldaxis, theta: theta }
      }
      return menu;
    });

    dispatch(updateMenu(menus));
  }

  return [onChangeAxis, onChangeTheta];
}

// translation特有のmenuに関する機能
const useTimeText = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onChangeTime = event => {
    const value = event.target.value;
    const menuId = Number(event.target.id.replace(/[^0-9]/g, ''));
    const type = event.target.name;

    // menuのanimationinfo(xyz)を更新する
    menus = menus.map(menu => {
      if (menu.id === menuId) {
        const oldStart = menu.time.start;
        const oldEnd = menu.time.end;
        delete menu.time;

        switch (type) {
          case "start":
            menu.time = { start: value, end: oldEnd }
            break;
          case "end":
            menu.time = { start: oldStart, end: value }
            break;
          default:
            break;
        }
      }
      return menu;
    });
    dispatch(updateMenu(menus));
  }

  return onChangeTime;
}


// translation特有のmenuに関する機能
const useXYZText = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onChangeXYZ = event => {
    const value = event.target.value;
    const menuId = Number(event.target.id.replace(/[^0-9]/g, ''));
    const xyz = event.target.name;

    // menuのanimationinfo(xyz)を更新する
    menus = menus.map(menu => {
      if (menu.id === menuId) {
        const oldX = menu.animationInfo.x;
        const oldY = menu.animationInfo.y;
        const oldZ = menu.animationInfo.z;
        delete menu.animationInfo;

        switch (xyz) {
          case "x":
            menu.animationInfo = { x: value, y: oldY, z: oldZ }
            break;
          case "y":
            menu.animationInfo = { x: oldX, y: value, z: oldZ }
            break;
          case "z":
            menu.animationInfo = { x: oldX, y: oldY, z: value }
            break;
          default:
            break;
        }
      }
      return menu;
    });
    dispatch(updateMenu(menus));
  }

  return onChangeXYZ;
}

const useClickAddAnimation = () => {
  // const dispatch = useDispatch();
  const menus = useSelector(state => state.animation.menus);
  const inputArray = useSelector(state => state.animation.inputArray);
  const mode = useSelector(state => state.animation.mode);

  const src = useSelector(state => state.model.src);
  const buffer = useSelector(state => state.model.buffer);
  const [error, setError] = useState(null);
  const dispatch = useDispatch();

  const onClickAddAnimation = () => {
    // modelをloadしていれば
    if (src !== "") {
      // menusがすべて埋まっているかチェック
      try {
        menus.forEach((menu) => {
          switch (menu.type) {
            case "translation":
              if (menu.animationInfo.x === "") throw new Error("xに空欄があります");
              if (menu.animationInfo.y === "") throw new Error("yに空欄があります");
              if (menu.animationInfo.z === "") throw new Error("zに空欄があります");
              break;
            case "rotation":
              if (menu.animationInfo.axis === "") throw new Error("axisの値が不正です");
              if (menu.animationInfo.theta === "") throw new Error("thetaに空欄があります");
              break;
            default:
              console.log("no type");
              break;
          }
        })

        const glb = new GLB(buffer);
        glb.addAnimation(menus, inputArray, mode);
        const state = makeGlbState(glb);
        // dipath model reducer
        dispatch(loadModel(glb.buffer, glb.src, state.timeArray));
      } catch (e) {
        setError(e);
      }
    }
  }

  return [onClickAddAnimation, error];
}

// card追加のボタンを押した時の機能
const useClickAddMenu = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);
  const src = useSelector(state => state.model.src);

  const onClickAddMenu = () => {
    // modelをloadしていれば
    if (src !== "") {
      // 追加するmenuを作る
      const ids = menus.map((menu) => {
        return Number(menu.id);
      })

      // menuの中のidの max + 1, なければ0
      const id = ids.length !== 0
        ? Math.max.apply(null, ids) + 1
        : 0

      const addMenu = {
        id: id,
        type: defaultState.menus[0].type,
        node: defaultState.menus[0].node,
        time: defaultState.menus[0].time,
        animationInfo: defaultState.menus[0].animationInfo
      }

      // もとのmenuと合体する(pushを使わない理由はreactのレンダリングが働かないから)
      menus = menus.concat(addMenu);
      dispatch(updateMenu(menus));
    }
  }
  return onClickAddMenu;
}

// menuのdeleteに関する機能
const useClickDelete = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onClickDelete = event => {
    const menuId = Number(event.target.id);
    menus = menus.filter((menu) => {
      return menu.id !== menuId
    })
    dispatch(updateMenu(menus));
  }

  return onClickDelete;
}

const useClickMode = () => {
  const dispatch = useDispatch();
  let menus = useSelector(state => state.animation.menus);

  const onClickMode = event => {
    let mode = event.target.name;
    menus = menus.map(menu => {
      switch (mode) {
        case "default":
          switch (menu.type) {
            case "translation":
              menu.animationInfo.x = 0
              menu.animationInfo.y = 0
              menu.animationInfo.z = 0
              break;
            case "rotation":
              menu.animationInfo.theta = 0
              break;
            default: break;
          }
          menu.time = 0;
          break;
        case "mat":
          menu.time = {
            start: 0,
            end: 0
          }
          break;
        default: break;
      }
      return menu;
    });
    switch (mode) {
      case "default": mode = "mat"; break;
      case "mat": mode = "default"; break;
      default: break;
    }
    dispatch(updateMode(mode));
    dispatch(updateMenu(menus));
  }

  return onClickMode;
}

