const AnimationMenuContainer = () => {
  const menus = useSelector(state => state.animation.menus);
  const type = useSelector(state => state.animation.type);
  const node = useSelector(state => state.animation.node);
  const inputName = useSelector(state => state.animation.inputName);
  const inputArray = useSelector(state => state.animation.inputArray);
  const mode = useSelector(state => state.animation.mode);
  const onChangeType = useChangeType();
  const onChangeTime = useTimeText();
  const onChangeXYZ = useXYZText();
  const [onChangeAxis, onChangeTheta] = useAxisTheta();
  const onChangeNode = useChangeNode();
  const onClickAddMenu = useClickAddMenu();
  const onClickDelete = useClickDelete();
  const onClickMode = useClickMode();
  const onChangeTimeMat = useChangeTimeMat();
  const onChangeXYZMat = useChangeXYZMat();
  const onChangeThetaMat = useChangeThetaMat();
  const [onClickAddAnimation, error] = useClickAddAnimation();

  let inputNames = [0];
  let inputIdx = [0];
  for (let i = 1; i < inputArray.length; i++) {
    inputNames.push(inputName + "[" + i + "]");
    inputIdx.push(i);
  }

  return (
    <AnimationMenuComponent
      menus={menus}
      type={type}
      node={node}
      inputNames={inputNames}
      inputArray={inputArray}
      inputIdx={inputIdx}
      mode={mode}
      onChangeType={onChangeType}
      onChangeNode={onChangeNode}
      onChangeTime={onChangeTime}
      onChangeXYZ={onChangeXYZ}
      onChangeTheta={onChangeTheta}
      onChangeAxis={onChangeAxis}
      onClickAddMenu={onClickAddMenu}
      onClickDelete={onClickDelete}
      onClickAddAnimation={onClickAddAnimation}
      onClickMode={onClickMode}
      onChangeTimeMat={onChangeTimeMat}
      onChangeXYZMat={onChangeXYZMat}
      onChangeThetaMat={onChangeThetaMat}
      error={error} // no used now
    />
  );
};

export default AnimationMenuContainer;